mapper.select:
select facts.code as code, coalesce(context.market, case when facts.code like '6%' then 'SH' else 'SZ' end) as market,
       facts.trade_date as tradeDate, facts.change_pct as changePct
  from cynexus_appl_market.trade_review_security_daily_fact facts
  left join cynexus_appl_market.trade_review_security_day_context context
    on context.trade_date=facts.trade_date and context.code=facts.code
 where facts.trade_date between #{startDate} and #{endDate}
   and facts.change_pct between #{minChangePct} and #{maxChangePct}
 order by facts.trade_date asc, facts.change_pct desc, facts.code asc
 limit #{limit}
